import type { Metadata } from 'next';

import { SITE } from '@/lib/site';

/** Per-page metadata with canonical URL, Open Graph and Twitter cards. `path` must end with "/".
 * The share image is generated by app/opengraph-image.tsx; it's set here explicitly because a page's own
 * openGraph/twitter objects replace the inherited ones. */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  const url = new URL(path, SITE.url).toString();
  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: {
      type: 'website',
      siteName: SITE.name,
      locale: SITE.locale,
      url,
      title: `${title} · ${SITE.name}`,
      description,
      images: [{ url: '/opengraph-image', width: 1200, height: 630, alt: `${SITE.name}: ${SITE.tagline}` }],
    },
    twitter: {
      card: 'summary_large_image',
      title: `${title} · ${SITE.name}`,
      description,
      images: ['/twitter-image'],
    },
  };
}
